)
VALUES
  ('business-formation', '{"en":"Business Formation","es":"Formación empresarial","fr":"Création d’entreprise","ht":"Kreyasyon biznis","ar":"تأسيس الأعمال"}', 'shield-check', 60, 60, TRUE, FALSE, 'planned'),
  ('digital-identity', '{"en":"Digital Identity","es":"Identidad digital","fr":"Identité numérique","ht":"Idantite dijital","ar":"الهوية الرقمية"}', 'ruler', 70, 70, TRUE, FALSE, 'planned'),
  ('online-presence', '{"en":"Online Presence","es":"Presencia en línea","fr":"Présence en ligne","ht":"Prezans sou entènèt","ar":"الحضور على الإنترنت"}', 'drill', 80, 80, TRUE, FALSE, 'planned'),
  ('business-operations', '{"en":"Business Operations","es":"Operaciones empresariales","fr":"Opérations commerciales","ht":"Operasyon biznis","ar":"عمليات الأعمال"}', 'wrench', 90, 90, TRUE, FALSE, 'planned')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO direct_catalog_services (
  category_id, slug, name_i18n, description_i18n, price_cents,
  currency_code, availability_days, available_days, sort_order, display_order,
  is_active, is_published, lifecycle_status, is_operationally_available,
  is_bookable, is_featured
)
SELECT c.id, v.slug, v.name_i18n::jsonb, v.description_i18n::jsonb, NULL,
  'USD', '[]'::jsonb, ARRAY[]::TEXT[], v.sort_order, v.sort_order,
  TRUE, FALSE, 'planned', FALSE, FALSE, FALSE
FROM direct_catalog_categories c
JOIN (VALUES
  ('business-formation', 'llc-or-business-entity-filing', '{"en":"LLC or Business Entity Filing","es":"Presentación de LLC o entidad comercial","fr":"Dépôt d’une LLC ou d’une entité commerciale","ht":"Depo LLC oswa antite biznis","ar":"تسجيل شركة ذات مسؤولية محدودة أو كيان تجاري"}', '{"en":"Prepare and submit a business entity filing package for administrator review.","es":"Prepara y presenta un paquete de registro de entidad comercial para revisión administrativa.","fr":"Préparez et soumettez un dossier de création d’entité commerciale pour examen administratif.","ht":"Prepare epi soumèt yon dosye anrejistreman antite biznis pou revizyon administratè.","ar":"إعداد وتقديم حزمة تسجيل كيان تجاري للمراجعة الإدارية."}', 10),
  ('business-formation', 'ein-federal-tax-id-registration', '{"en":"EIN (Federal Tax ID) Registration","es":"Registro de EIN (número fiscal federal)","fr":"Demande d’EIN (numéro fiscal fédéral)","ht":"Enskripsyon EIN (ID taks federal)","ar":"تسجيل رقم EIN (المعرف الضريبي الفيدرالي)"}', '{"en":"Guide the information-gathering and submission steps for a federal tax ID request.","es":"Guía la recopilación de información y los pasos de presentación para solicitar un número fiscal federal.","fr":"Accompagnez la collecte d’informations et les étapes de demande d’un numéro fiscal fédéral.","ht":"Gide koleksyon enfòmasyon ak etap soumèt demann pou yon ID taks federal.","ar":"إرشاد جمع المعلومات وخطوات تقديم طلب المعرف الضريبي الفيدرالي."}', 20),
  ('business-formation', 'business-mailing-address-setup', '{"en":"Business Mailing Address Setup","es":"Configuración de dirección postal comercial","fr":"Mise en place d’une adresse postale commerciale","ht":"Mete adrès postal biznis","ar":"إعداد عنوان بريدي تجاري"}', '{"en":"Set up a business mailing-address option and organize the required account details.","es":"Configura una opción de dirección postal comercial y organiza los datos necesarios de la cuenta.","fr":"Mettez en place une option d’adresse postale commerciale et organisez les informations requises.","ht":"Mete yon opsyon adrès postal biznis epi òganize detay kont ki nesesè yo.","ar":"إعداد خيار عنوان بريدي تجاري وتنظيم تفاصيل الحساب المطلوبة."}', 30),
  ('business-formation', 'operating-documents-folder', '{"en":"Operating Documents Folder","es":"Carpeta de documentos operativos","fr":"Dossier des documents d’exploitation","ht":"Dosye dokiman operasyon","ar":"مجلد مستندات التشغيل"}', '{"en":"Create an organized digital folder for operating records and business documents.","es":"Crea una carpeta digital organizada para los registros operativos y documentos comerciales.","fr":"Créez un dossier numérique organisé pour les registres d’exploitation et les documents commerciaux.","ht":"Kreye yon dosye dijital òganize pou dosye operasyon ak dokiman biznis.","ar":"إنشاء مجلد رقمي منظم لسجلات التشغيل ومستندات الأعمال."}', 40),
  ('digital-identity', 'domain-name-registration', '{"en":"Domain Name Registration","es":"Registro de nombre de dominio","fr":"Enregistrement de nom de domaine","ht":"Enskripsyon non domèn","ar":"تسجيل اسم النطاق"}', '{"en":"Find and register a suitable domain name for the business.","es":"Busca y registra un nombre de dominio adecuado para el negocio.","fr":"Recherchez et enregistrez un nom de domaine adapté à l’entreprise.","ht":"Jwenn epi anrejistre yon non domèn ki apwopriye pou biznis la.","ar":"البحث عن اسم نطاق مناسب للأعمال وتسجيله."}', 10),
  ('digital-identity', 'professional-email-setup', '{"en":"Professional Email Setup","es":"Configuración de correo electrónico profesional","fr":"Configuration d’une adresse e-mail professionnelle","ht":"Mete imèl pwofesyonèl","ar":"إعداد بريد إلكتروني مهني"}', '{"en":"Configure a professional business mailbox such as you@yourbusiness.com.","es":"Configura un buzón profesional para el negocio, como you@yourbusiness.com.","fr":"Configurez une boîte professionnelle pour l’entreprise, comme you@yourbusiness.com.","ht":"Konfigire yon bwat imèl pwofesyonèl pou biznis la, tankou you@yourbusiness.com.","ar":"إعداد صندوق بريد مهني للأعمال مثل you@yourbusiness.com."}', 20),
  ('digital-identity', 'dedicated-business-phone-number', '{"en":"Dedicated Business Phone Number","es":"Número de teléfono comercial dedicado","fr":"Numéro de téléphone professionnel dédié","ht":"Nimewo telefòn biznis dedye","ar":"رقم هاتف تجاري مخصص"}', '{"en":"Set up a dedicated business phone number and its basic routing details.","es":"Configura un número de teléfono comercial dedicado y sus detalles básicos de enrutamiento.","fr":"Mettez en place un numéro professionnel dédié et ses paramètres de routage de base.","ht":"Mete yon nimewo telefòn biznis dedye ak detay debaz sou routaj li.","ar":"إعداد رقم هاتف تجاري مخصص وتفاصيل التوجيه الأساسية."}', 30),
  ('digital-identity', 'logo-and-basic-brand-kit', '{"en":"Logo & Basic Brand Kit","es":"Logotipo y kit básico de marca","fr":"Logo et kit de marque de base","ht":"Logo ak twous mak debaz","ar":"شعار وحزمة هوية أساسية"}', '{"en":"Create a simple logo direction with starter colors and fonts for consistent use.","es":"Crea una dirección de logotipo sencilla con colores y fuentes iniciales para un uso coherente.","fr":"Créez une orientation de logo simple avec des couleurs et des polices de départ pour une utilisation cohérente.","ht":"Kreye yon direksyon logo senp ak koulè ak polis debaz pou itilizasyon ki konsistan.","ar":"إنشاء تصور بسيط للشعار مع ألوان وخطوط أساسية للاستخدام المتسق."}', 40),
  ('online-presence', 'website-build', '{"en":"Website Build","es":"Creación de sitio web","fr":"Création de site web","ht":"Konstriksyon sit entènèt","ar":"إنشاء موقع إلكتروني"}', '{"en":"Build a basic website with homepage, services, about, and contact sections.","es":"Crea un sitio web básico con secciones de inicio, servicios, información y contacto.","fr":"Créez un site web de base avec des sections accueil, services, à propos et contact.","ht":"Kreye yon sit entènèt debaz ak paj akèy, sèvis, enfòmasyon, ak kontak.","ar":"إنشاء موقع إلكتروني أساسي يضم أقسام الصفحة الرئيسية والخدمات ومن نحن والاتصال."}', 10),
  ('online-presence', 'contact-form-and-lead-capture', '{"en":"Contact Form & Lead Capture","es":"Formulario de contacto y captación de clientes","fr":"Formulaire de contact et capture de prospects","ht":"Fòm kontak ak koleksyon kliyan potansyèl","ar":"نموذج اتصال وجمع العملاء المحتملين"}', '{"en":"Add a contact form and a simple workflow for collecting and routing new leads.","es":"Añade un formulario de contacto y un flujo sencillo para recopilar y dirigir nuevos clientes potenciales.","fr":"Ajoutez un formulaire de contact et un flux simple pour recueillir et orienter les nouveaux prospects.","ht":"Ajoute yon fòm kontak ak yon workflow senp pou kolekte epi voye nouvo kliyan potansyèl yo.","ar":"إضافة نموذج اتصال وسير عمل بسيط لجمع العملاء المحتملين الجدد وتوجيههم."}', 20),
  ('online-presence', 'google-business-profile-setup', '{"en":"Google Business Profile Setup","es":"Configuración del Perfil de Negocio de Google","fr":"Configuration de la fiche d’établissement Google","ht":"Mete pwofil biznis Google","ar":"إعداد الملف التجاري على Google"}', '{"en":"Prepare and configure the business information used for a Google Business Profile.","es":"Prepara y configura la información comercial utilizada en un Perfil de Negocio de Google.","fr":"Préparez et configurez les informations commerciales utilisées dans une fiche d’établissement Google.","ht":"Prepare epi konfigire enfòmasyon biznis yo itilize pou yon pwofil biznis Google.","ar":"إعداد وتهيئة معلومات الأعمال المستخدمة في الملف التجاري على Google."}', 30),
  ('online-presence', 'social-media-handle-reservation', '{"en":"Social Media Handle Reservation","es":"Reserva de nombres de usuario en redes sociales","fr":"Réservation de noms d’utilisateur sur les réseaux sociaux","ht":"Rezève non itilizatè sou rezo sosyal","ar":"حجز أسماء المستخدمين على وسائل التواصل الاجتماعي"}', '{"en":"Check and reserve consistent social media handles where they are available.","es":"Comprueba y reserva nombres de usuario coherentes en redes sociales cuando estén disponibles.","fr":"Vérifiez et réservez des noms d’utilisateur cohérents sur les réseaux sociaux lorsqu’ils sont disponibles.","ht":"Verifye epi rezève non itilizatè ki konsistan sou rezo sosyal lè yo disponib.","ar":"التحقق من أسماء مستخدمين متسقة على وسائل التواصل الاجتماعي وحجزها عند توفرها."}', 40),
  ('business-operations', 'payment-processor-setup', '{"en":"Payment Processor Setup","es":"Configuración de procesador de pagos","fr":"Configuration d’un processeur de paiement","ht":"Mete procesè peman","ar":"إعداد معالج الدفع"}', '{"en":"Configure a payment processor such as Stripe, Square, or PayPal for administrator review.","es":"Configura un procesador de pagos como Stripe, Square o PayPal para la revisión administrativa.","fr":"Configurez un processeur de paiement comme Stripe, Square ou PayPal pour examen administratif.","ht":"Konfigire yon procesè peman tankou Stripe, Square, oswa PayPal pou revizyon administratè.","ar":"إعداد معالج دفع مثل Stripe أو Square أو PayPal للمراجعة الإدارية."}', 10),
  ('business-operations', 'online-scheduling-system', '{"en":"Online Scheduling System","es":"Sistema de programación en línea","fr":"Système de planification en ligne","ht":"Sistèm planifikasyon sou entènèt","ar":"نظام جدولة عبر الإنترنت"}', '{"en":"Set up a booking page and the basic scheduling workflow for clients.","es":"Configura una página de reservas y el flujo básico de programación para clientes.","fr":"Mettez en place une page de réservation et le flux de planification de base pour les clients.","ht":"Mete yon paj rezèvasyon ak workflow planifikasyon debaz pou kliyan yo.","ar":"إعداد صفحة حجز وسير عمل أساسي للجدولة للعملاء."}', 20),
  ('business-operations', 'client-intake-form-and-workflow', '{"en":"Client Intake Form & Workflow","es":"Formulario y flujo de incorporación de clientes","fr":"Formulaire et processus d’accueil des clients","ht":"Fòm ak workflow akèy kliyan","ar":"نموذج وسير عمل استقبال العملاء"}', '{"en":"Create a client intake form and an organized workflow for reviewing new requests.","es":"Crea un formulario de incorporación y un flujo organizado para revisar nuevas solicitudes.","fr":"Créez un formulaire d’accueil et un processus organisé pour examiner les nouvelles demandes.","ht":"Kreye yon fòm akèy kliyan ak yon workflow òganize pou revize nouvo demann yo.","ar":"إنشاء نموذج استقبال للعملاء وسير عمل منظم لمراجعة الطلبات الجديدة."}', 30),
  ('business-operations', 'invoice-and-proposal-templates', '{"en":"Invoice & Proposal Templates","es":"Plantillas de facturas y propuestas","fr":"Modèles de factures et de propositions","ht":"Modèl fakti ak pwopozisyon","ar":"قوالب الفواتير والعروض"}', '{"en":"Prepare reusable invoice and proposal templates for common business engagements.","es":"Prepara plantillas reutilizables de facturas y propuestas para trabajos comerciales habituales.","fr":"Préparez des modèles réutilisables de factures et de propositions pour les engagements courants.","ht":"Prepare modèl fakti ak pwopozisyon ki ka sèvi ankò pou travay biznis komen.","ar":"إعداد قوالب قابلة لإعادة الاستخدام للفواتير والعروض للأعمال المعتادة."}', 40),
  ('business-operations', 'basic-bookkeeping-starter-system', '{"en":"Basic Bookkeeping Starter System","es":"Sistema inicial básico de contabilidad","fr":"Système de démarrage pour la comptabilité de base","ht":"Sistèm debaz pou kòmanse kontablite","ar":"نظام أولي أساسي لمسك الدفاتر"}', '{"en":"Organize a basic bookkeeping starter system and record-keeping workflow.","es":"Organiza un sistema inicial básico de contabilidad y un flujo para conservar registros.","fr":"Organisez un système de démarrage pour la comptabilité de base et le suivi des registres.","ht":"Òganize yon sistèm debaz pou kòmanse kontablite ak yon workflow pou kenbe dosye.","ar":"تنظيم نظام أولي أساسي لمسك الدفاتر وسير عمل لحفظ السجلات."}', 50)
) AS v(category_slug, slug, name_i18n, description_i18n, sort_order)
  ON c.slug = v.category_slug
ON CONFLICT (slug) DO NOTHING;

INSERT INTO catalog_status_history (item_type, item_id, from_status, to_status, changed_by, reason)
SELECT 'category', id, NULL, lifecycle_status, NULL, 'Seeded Business Launch master catalog'
FROM direct_catalog_categories c
WHERE c.slug IN ('business-formation', 'digital-identity', 'online-presence', 'business-operations')
  AND NOT EXISTS (
    SELECT 1 FROM catalog_status_history h
    WHERE h.item_type = 'category' AND h.item_id = c.id
  );

INSERT INTO catalog_status_history (item_type, item_id, from_status, to_status, changed_by, reason)
SELECT 'service', id, NULL, lifecycle_status, NULL, 'Seeded Business Launch master catalog'
FROM direct_catalog_services s
WHERE s.slug IN (
  'llc-or-business-entity-filing', 'ein-federal-tax-id-registration',
  'business-mailing-address-setup', 'operating-documents-folder',
  'domain-name-registration', 'professional-email-setup',
  'dedicated-business-phone-number', 'logo-and-basic-brand-kit',
  'website-build', 'contact-form-and-lead-capture',
  'google-business-profile-setup', 'social-media-handle-reservation',
  'payment-processor-setup', 'online-scheduling-system',
  'client-intake-form-and-workflow', 'invoice-and-proposal-templates',
  'basic-bookkeeping-starter-system'
)
  AND NOT EXISTS (
    SELECT 1 FROM catalog_status_history h
    WHERE h.item_type = 'service' AND h.item_id = s.id
  );
